## chamadas
- bash (intenção: Restoring rate-limit error body clone behavior | comando: python3 - <<'PY'
from pathlib import Path
p = Path('src/http/client.rs')
s = p.read_text()
old = '''                context: Box::new(ErrorContext {
                    operation: Some(operation.to_string()),
                    http_status: Some(http_status),
                    response_body: Some(body),
                    api_errors,
                }),
            });
        }

        Err(GitLabError::api('''
new = '''                context: Box::new(ErrorContext {
                    operation: Some(operation.to_string()),
                    http_status: Some(http_status),
                    response_body: Some(body.clone()),
                    api_errors,
                }),
            });
        }

        Err(GitLabError::api('''
assert old in s
p.write_text(s.replace(old, new, 1))
PY
echo restored)

